using Npgsql;
using T1.Core.Seeding;
using T1.IntegrationTests.Infrastructure;

namespace T1.IntegrationTests;

/// <summary>2. Data for T1 generated by a stored procedure: at least 100 000 rows over three or four months.</summary>
public sealed class Req2_DataGenerationTests(PostgresClusterFixture cluster)
{
    private static CancellationToken Ct => TestContext.Current.CancellationToken;

    [Fact]
    public async Task Default_seed_generates_120k_rows_over_the_last_three_months_and_the_current_one()
    {
        await using var db = await cluster.CreateDatabasesAsync("req2a");
        await db.MigratePrimaryAsync();

        var generated = await db.CreateSeeder(new SeedOptions()).SeedIfEmptyAsync(Ct);
        var now = DateTime.UtcNow;

        Assert.Equal(120_000, generated);
        var stats = (await db.Primary.RowsAsync("""
            SELECT count(*),
                   count(DISTINCT date_trunc('month', op_date, 'UTC')),
                   min(op_date),
                   max(op_date),
                   count(DISTINCT operation_guid),
                   count(*) FILTER (WHERE state = 0),
                   count(DISTINCT message ->> 'operation_type'),
                   min((message ->> 'client_id')::bigint),
                   max((message ->> 'client_id')::bigint)
              FROM t1
            """))[0];

        Assert.Equal(120_000L, stats[0]);
        Assert.Equal(4L, stats[1]);                         // M-3, M-2, M-1 and the current month
        var firstDay = new DateTime(now.Year, now.Month, 1, 0, 0, 0, DateTimeKind.Utc).AddMonths(-3);
        Assert.InRange((DateTime)stats[2]!, firstDay, firstDay.AddDays(1));
        Assert.InRange((DateTime)stats[3]!, now.AddDays(-1), now);
        Assert.Equal(120_000L, stats[4]);
        Assert.InRange((long)stats[5]!, 600L, 1_800L);      // ~1% left pending
        Assert.Equal(2L, stats[6]);
        Assert.Equal(1L, stats[7]);
        Assert.Equal(1000L, stats[8]);

        Assert.Equal(120_000L, await db.Primary.ScalarAsync<long>("SELECT count(*) FROM t1_operation_guid"));
        Assert.Equal(
            await db.Primary.ScalarAsync<decimal>("SELECT sum(amount) FROM t1 WHERE state = 1"),
            await db.Primary.ScalarAsync<decimal>("SELECT sum(total_amount) FROM t1_client_totals"));

        Assert.Equal(0, await db.CreateSeeder(new SeedOptions()).SeedIfEmptyAsync(Ct));   // t1 has data now
    }

    [Fact]
    public async Task Interrupted_seed_leaves_nothing_behind()
    {
        await using var db = await cluster.CreateDatabasesAsync("req2b");
        await db.MigratePrimaryAsync();

        using var cancel = CancellationTokenSource.CreateLinkedTokenSource(Ct);
        cancel.CancelAfter(TimeSpan.FromMilliseconds(700));
        await Assert.ThrowsAnyAsync<Exception>(() => db.CreateSeeder(new SeedOptions { BatchSize = 5_000 }).SeedIfEmptyAsync(cancel.Token));

        Assert.Equal(0L, await db.Primary.ScalarAsync<long>("SELECT count(*) FROM t1"));
        Assert.Equal(120_000, await db.CreateSeeder(new SeedOptions()).SeedIfEmptyAsync(Ct));   // the next start seeds again
    }

    [Fact]
    public async Task Procedure_can_be_called_directly_for_an_explicit_period()
    {
        await using var db = await cluster.CreateDatabasesAsync("req2c");
        await db.MigratePrimaryAsync();

        await db.Primary.ExecuteAsync("CALL t1_generate_data(p_rows => 100000, p_from => '2026-03-01', p_to => '2026-07-01', p_pending_share => 0)");

        var stats = (await db.Primary.RowsAsync("""
            SELECT count(*), min(op_date) >= '2026-03-01', max(op_date) < '2026-07-01',
                   count(DISTINCT tableoid), count(*) FILTER (WHERE state = 0),
                   bool_and(abs(extract(epoch FROM uuid_extract_timestamp(operation_guid) - op_date)) < 0.01),
                   (SELECT count(*) FROM t1_partition_months())
              FROM t1
            """))[0];

        Assert.Equal(100_000L, stats[0]);
        Assert.Equal(true, stats[1]);
        Assert.Equal(true, stats[2]);
        Assert.Equal(4L, stats[3]);      // March .. June
        Assert.Equal(0L, stats[4]);
        Assert.Equal(true, stats[5]);    // UUIDv7 carries op_date
        Assert.Equal(4L, stats[6]);      // no empty partition for July
        Assert.Equal(0L, await db.Primary.ScalarAsync<long>(
            "SELECT count(*) FROM (SELECT op_date < lag(op_date) OVER (ORDER BY id) AS out_of_order FROM t1) s WHERE out_of_order"));
    }

    [Fact]
    public async Task Result_does_not_depend_on_the_session_time_zone()
    {
        await using var db = await cluster.CreateDatabasesAsync("req2d");
        await db.MigratePrimaryAsync();

        // the period ends 30 minutes before a UTC month boundary and crosses a DST switch in Kyiv
        await using (var connection = await db.Primary.OpenConnectionAsync(Ct))
        {
            foreach (var sql in new[]
                     {
                         "SET TimeZone = 'Europe/Kyiv'",
                         "CALL t1_generate_data(p_rows => 20000, p_from => '2031-10-20 00:00+00', p_to => '2031-10-31 23:30+00')",
                     })
            {
                await using var command = new NpgsqlCommand(sql, connection);
                await command.ExecuteNonQueryAsync(Ct);
            }
        }

        Assert.Equal(0L, await db.Primary.ScalarAsync<long>(
            "SELECT count(*) FROM t1 WHERE op_date < '2031-10-20 00:00+00' OR op_date >= '2031-10-31 23:30+00'"));
        Assert.Equal(0L, await db.Primary.ScalarAsync<long>(
            "SELECT count(*) FROM t1 WHERE abs(extract(epoch FROM uuid_extract_timestamp(operation_guid) - op_date)) > 0.01"));
    }

    [Fact]
    public async Task Rows_are_uniform_when_the_count_is_not_a_multiple_of_the_batch()
    {
        await using var db = await cluster.CreateDatabasesAsync("req2e");
        await db.MigratePrimaryAsync();

        await db.Primary.ExecuteAsync("CALL t1_generate_data(p_rows => 25000, p_from => '2030-08-01', p_to => '2030-10-01', p_batch_size => 20000)");

        var perMonth = (await db.Primary.RowsAsync("SELECT count(*) FROM t1 GROUP BY date_trunc('month', op_date, 'UTC') ORDER BY 1")).Select(r => (long)r[0]!).ToList();
        Assert.Equal(2, perMonth.Count);
        Assert.All(perMonth, count => Assert.InRange(count, 12_000L, 13_000L));   // 31 and 30 days
    }

    [Fact]
    public async Task Only_the_owner_generates_data()
    {
        await using var db = await cluster.CreateDatabasesAsync("req2g");
        await db.MigratePrimaryAsync();
        await using var role = await db.CreateDmlRoleAsync();

        var error = await Assert.ThrowsAsync<PostgresException>(() => role.ExecuteAsync("CALL t1_generate_data(p_rows => 10)"));

        Assert.Equal(PostgresErrorCodes.InsufficientPrivilege, error.SqlState);
        Assert.Equal(0L, await db.Primary.ScalarAsync<long>("SELECT count(*) FROM t1"));
    }

    [Theory]
    [InlineData("p_rows => 0")]
    [InlineData("p_pending_share => 2")]
    [InlineData("p_from => '2026-05-01', p_to => '2026-04-01'")]
    public async Task Procedure_validates_its_arguments(string arguments)
    {
        await using var db = await cluster.CreateDatabasesAsync("req2f");
        await db.MigratePrimaryAsync();

        await Assert.ThrowsAsync<PostgresException>(() => db.Primary.ExecuteAsync($"CALL t1_generate_data({arguments})"));
    }
}
